data.script:
if (!draft.content.trim()) { context.fail('The draft is empty.'); }
else {
  const title = draft.title, body = draft.processTemplate('[[body]]');
  const callback = CallbackURL.create();
  callback.baseURL = 'bear://x-callback-url/create?title=' + encodeURIComponent(title) + '&text=' + encodeURIComponent(body);
  if (!callback.open()) {
    if (callback.status === 'cancelled') context.cancel();
    else context.fail('Bear did not confirm the new note.');
  }
}
